#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using P = pair<int, int>;
const ll MOD = 1000000009;

ll mod_pow(ll base, ll exp, ll m = MOD) {
    ll res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % m;
        base = base * base % m;
        exp >>= 1;
    }
    return res;
}

struct Mint {
    ll val;
    Mint() : val(0) {}
    Mint(ll v) {
        val = v % MOD;
        if (val < 0) val += MOD;
    }
    operator int() const { return (int)val; }
    Mint& operator+=(const Mint& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    Mint& operator-=(const Mint& other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }
    Mint& operator*=(const Mint& other) {
        val = (val * other.val) % MOD;
        return *this;
    }
    friend Mint operator+(Mint a, const Mint& b) { return a += b; }
    friend Mint operator-(Mint a, const Mint& b) { return a -= b; }
    friend Mint operator*(Mint a, const Mint& b) { return a *= b; }
    friend Mint operator^(Mint a, ll n) {
        Mint res(1);
        while (n > 0) {
            if (n & 1) res *= a;
            a *= a;
            n >>= 1;
        }
        return res;
    }
};

ll inv(ll a, ll p) {
    if (a == 1) return 1;
    return (1 - p * inv(p % a, a)) / a + p;
}

const int MAX = 262144;
Mint fact[MAX], inv_fact[MAX];

void init_factorials() {
    fact[0] = Mint(1);
    for (int i = 1; i < MAX; i++) {
        fact[i] = fact[i - 1] * Mint(i);
    }
    inv_fact[MAX - 1] = Mint(1) / fact[MAX - 1];
    for (int i = MAX - 2; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1] * Mint(i + 1);
    }
}

Mint comb(int a, int b) {
    if (a < 0 || b < 0 || a < b) return Mint(0);
    return fact[a] * inv_fact[b] * inv_fact[a - b];
}

pair<Mint, Mint> multiply(pair<Mint, Mint> a, pair<Mint, Mint> b) {
    return {a.first * b.first, a.second * b.first + a.first * b.second};
}

pair<Mint, Mint> add(pair<Mint, Mint> a, pair<Mint, Mint> b) {
    return {a.first + b.first, a.second + b.second};
}

pair<Mint, Mint> dp[501];
bool used[501];

void setup() {
    init_factorials();
    dp[0] = {Mint(1), Mint(0)};
    dp[1] = {Mint(2), Mint(0)};
    for (int n = 2; n <= 500; n++) {
        for (int j = 0; j < n; j++) {
            Mint cnt = Mint(n + 1);
            Mint sum = Mint(0);
            for (int k = 0; k < n; k++) {
                sum += abs(j - k);
            }
            auto left = dp[j];
            auto right = dp[n - 1 - j];
            auto x = multiply(left, right);
            x.first *= comb(n - 1, j);
            x.second *= comb(n - 1, j);
            x.first *= cnt;
            x.second *= cnt + sum;
            dp[n] = add(dp[n], x);
        }
    }
}

pair<Mint, Mint> dp2[502][501];

void process() {
    int n, m; cin >> n >> m;
    setup();
    for (int i = 0; i <= n; i++) {
        for (int k = 0; k <= m; k++) {
            dp2[i][k] = {Mint(0), Mint(0)};
        }
    }
    dp2[0][0] = {Mint(1), Mint(0)};
    for (int i = 0; i < n; i++) {
        for (int k = 0; k <= m; k++) {
            if (dp2[i][k].first.val == 0 && dp2[i][k].second.val == 0) continue;
            for (int j = i; j < n; j++) {
                int ni = j + 2;
                if (ni > n) ni = n;
                int nk = k + j - i + 1;
                if (nk <= m) {
                    auto x = multiply(dp2[i][k], dp[j - i + 1]);
                    x.first *= comb(nk, k);
                    x.second *= comb(nk, k);
                    dp2[ni][nk] = add(dp2[ni][nk], x);
                }
            }
            if (i + 1 <= n && k <= m) {
                dp2[i + 1][k] = add(dp2[i + 1][k], dp2[i][k]);
            }
        }
    }
    cout << (int)dp2[n][m].second << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    process();
    return 0;
}
